        "            this.saveRect();\n"
        "        };\n"
        "\n"
        "        target.addEventListener (\"pointermove\", onMove);\n"
        "        target.addEventListener (\"pointerup\", up);\n"
        "        target.addEventListener (\"pointercancel\", up);\n"
        "    }\n"
        "}\n";
