        "            return `${_type} ${JSON.stringify (rest)}`;\n"
        "        }\n"
        "\n"
        "        return JSON.stringify (value);\n"
        "    }\n"
        "    catch (e)\n"
        "    {\n"
        "        return String (value);\n"
        "    }\n"
        "}\n";
